151:       if (['Space', 'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Tab'].includes(k)) e.preventDefault();
152:       this.keys.add(k);
153:       if (k === 'KeyR' && this.state === 'playing') this.player.reload();
154:       if (this.state === 'playing' && (k === 'Digit1' || k === 'Digit2' || k === 'Digit3')) {
155:         this.player.switchWeapon(Number(k.slice(-1)) - 1);
156:       }
157:       if (k === 'KeyQ' && this.state === 'playing') this.player.cycleWeapon();
158:       if (k === 'Escape') {
159:         if (this.state === 'playing') this.pause();
160:         else if (this.state === 'paused') this.resume();
161:       }
162:       if (k === 'KeyE') this.interactHeld = true;
163:       if (k === 'KeyM') this.toggleMute();
164:     });
165: 
166:     window.addEventListener('keyup', (e) => {
167:       this.keys.delete(e.code);
168:       if (e.code === 'KeyE') this.interactHeld = false;
169:     });
170: 
171:     window.addEventListener('blur', () => {
172:       this.keys.clear();
173:       this.firing = false;
174:       this.ads = false;
175:       this.interactHeld = false;
176:       if (this.state === 'playing') this.pause();
177:     });
178: 
179:     canvas.addEventListener('mousedown', (e) => {
180:       if (this.state !== 'playing') return;
181:       if (e.button === 0) {
182:         this.firing = true;
183:         this.dragging = true;
184:         if (!this.locked) this.requestLock();
185:       }
186:       if (e.button === 2) this.ads = true;
187:     });
188: 
189:     window.addEventListener('mouseup', (e) => {
190:       if (e.button === 0) {
191:         this.firing = false;
192:         this.dragging = false;
193:       }
194:       if (e.button === 2) this.ads = false;
195:     });
196: 
197:     canvas.addEventListener('contextmenu', (e) => e.preventDefault());
198: 
199:     document.addEventListener('mousemove', (e) => {
200:       if (this.state !== 'playing') return;
201:       if (this.locked) {
202:         this.player.look(e.movementX || 0, e.movementY || 0);
203:       } else if (this.dragging) {
204:         this.player.look((e.movementX || 0) * 1.4, (e.movementY || 0) * 1.4);
205:       }
206:     });
207: 
208:     document.addEventListener('pointerlockchange', () => {
209:       const locked = document.pointerLockElement === canvas;
210:       if (this.locked && !locked && this.state === 'playing') {
211:         this.pause();
212:       }
213:       this.locked = locked;
214:       this.wasLocked = locked;
215:     });
