221:     // touch controls --------------------------------------------------
222:     const stickZone = document.getElementById('stick-zone');
223:     const knob = document.getElementById('stick-knob');
224:     let stickId = null;
225:     let stickCenter = { x: 0, y: 0 };
226: 
227:     const setStick = (dx, dy) => {
228:       const max = 55;
229:       const len = Math.hypot(dx, dy) || 1;
230:       const cl = Math.min(1, len / max);
231:       const nx = (dx / len) * cl;
232:       const ny = (dy / len) * cl;
233:       this.touch.strafe = nx;
234:       this.touch.forward = -ny;
235:       knob.style.transform = `translate(${nx * 34}px, ${ny * 34}px)`;
236:     };
237:     const resetStick = () => {
238:       stickId = null;
239:       this.touch.strafe = 0;
240:       this.touch.forward = 0;
241:       knob.style.transform = 'translate(0px, 0px)';
242:     };
243: 
244:     if (stickZone) {
245:       stickZone.addEventListener('pointerdown', (e) => {
246:         stickId = e.pointerId;
247:         stickZone.setPointerCapture(e.pointerId);
248:         const r = stickZone.getBoundingClientRect();
249:         stickCenter = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
250:         setStick(e.clientX - stickCenter.x, e.clientY - stickCenter.y);
251:         e.preventDefault();
252:       });
253:       stickZone.addEventListener('pointermove', (e) => {
254:         if (e.pointerId !== stickId) return;
255:         setStick(e.clientX - stickCenter.x, e.clientY - stickCenter.y);
256:       });
257:       stickZone.addEventListener('pointerup', resetStick);
258:       stickZone.addEventListener('pointercancel', resetStick);
259:     }
260: 
261:     let lookId = null;
262:     let lastX = 0, lastY = 0;
263:     canvas.addEventListener('pointerdown', (e) => {
264:       if (e.pointerType !== 'touch' || this.state !== 'playing') return;
265:       if (e.clientX < window.innerWidth * 0.35) return;
266:       lookId = e.pointerId;
267:       lastX = e.clientX;
268:       lastY = e.clientY;
269:     });
270:     canvas.addEventListener('pointermove', (e) => {
271:       if (e.pointerId !== lookId) return;
272:       this.player.look((e.clientX - lastX) * 1.5, (e.clientY - lastY) * 1.5);
273:       lastX = e.clientX;
274:       lastY = e.clientY;
275:     });
276:     const endLook = (e) => { if (e.pointerId === lookId) lookId = null; };
277:     canvas.addEventListener('pointerup', endLook);
278:     canvas.addEventListener('pointercancel', endLook);
279: 
280:     for (const btn of document.querySelectorAll('[data-touch]')) {
281:       const action = btn.dataset.touch;
282:       btn.addEventListener('pointerdown', (e) => {
283:         e.preventDefault();
284:         this.audio.resume();
285:         if (action === 'fire') this.touch.fire = true;
286:         if (action === 'interact') this.touch.interact = true;
287:         if (action === 'reload') this.player.reload();
288:         if (action === 'swap') this.player.cycleWeapon();
289:         if (action === 'aim') {
290:           this.touch.ads = true;
291:           btn.classList.add('active');
292:         }
293:       });
294:       const release = (e) => {
295:         e.preventDefault();
296:         if (action === 'fire') this.touch.fire = false;
297:         if (action === 'interact') this.touch.interact = false;
298:         if (action === 'aim') {
299:           this.touch.ads = false;
300:           btn.classList.remove('active');
301:         }
302:       };
303:       btn.addEventListener('pointerup', release);
304:       btn.addEventListener('pointercancel', release);
305:       btn.addEventListener('pointerleave', release);
306:     }
307:   }
