437:     } else if (this.state === 'menu') {
438:       this.updateMenu(dt);
439:     } else if (this.state === 'dead') {
440:       this.deathT += dt;
441:       this.updateDeath(dt);
442:     } else if (this.state === 'extracted') {
443:       this.updateAmbient(dt);
444:     } else if (this.state === 'paused') {
445:       // hold the frame
446:     }
447: 
448:     this.ui.update(dt);
449:     this.renderer.render(this.scene, this.camera);
