454:     const a = t * 0.055;
455:     const y = terrainHeight(HUB.x, HUB.z);
456:     this.camera.position.set(
457:       HUB.x + Math.cos(a) * 31,
458:       y + 8.6 + Math.sin(t * 0.35) * 0.35,
459:       HUB.z + 15 + Math.sin(a) * 9
460:     );
461:     this.camera.lookAt(REFINERY.x * 0.4, 5.5, REFINERY.z - 34);
462:     this.camera.rotation.z = 0;
463: 
464:     this.world.update(dt, t, false, null);
465:     this.effects.update(dt);
466:     this.ui.updateMarkers(this.camera, false);
467:     for (const d of this.enemies) d.update(dt, this.ctx);
468:     for (const c of this.crates) c.update(dt);
469:     for (const n of this.nodes) n.update(dt);
470:   }
