481:   updatePlaying(dt) {
482:     const input = this.input;
483:     const pad = this.gamepad;
484:     const padOn = pad.connected;
485:     input.forward = (this.keys.has('KeyW') ? 1 : 0) - (this.keys.has('KeyS') ? 1 : 0) + this.touch.forward + (padOn ? -pad.moveY : 0);
486:     input.strafe = (this.keys.has('KeyD') ? 1 : 0) - (this.keys.has('KeyA') ? 1 : 0) + this.touch.strafe + (padOn ? pad.moveX : 0);
487:     input.sprint = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || (padOn && pad.sprint);
488:     input.jump = this.keys.has('Space') || (padOn && pad.jump);
489:     input.fire = this.firing || this.touch.fire || (padOn && pad.fire);
490:     input.ads = this.ads || this.touch.ads || (padOn && pad.aim);
491:     input.interact = this.interactHeld || this.touch.interact || (padOn && pad.interact);
492: 
493:     if (padOn && (pad.lookX !== 0 || pad.lookY !== 0)) {
494:       // Right stick is rate-controlled: the deflection becomes turn speed.
495:       this.player.look(pad.lookX * 900 * dt, pad.lookY * 820 * dt);
496:     }
497: 
498:     this.player.update(dt, input, this.world.colliders);
499:     if (this.state !== 'playing') return;
500: 
501:     this.ctx.storm = this.storm.active;
502:     for (const d of this.enemies) d.update(dt, this.ctx);
503: 
504:     for (let i = this.bolts.length - 1; i >= 0; i--) {
505:       const b = this.bolts[i];
506:       b.update(dt, this.ctx);
507:       if (!b.alive) this.bolts.splice(i, 1);
508:     }
509: 
510:     for (let i = this.pickups.length - 1; i >= 0; i--) {
511:       const p = this.pickups[i];
512:       p.update(dt, this.time, this.player);
513:       const dx = p.group.position.x - this.player.pos.x;
514:       const dy = p.group.position.y - (this.player.pos.y + 1.0);
515:       const dz = p.group.position.z - this.player.pos.z;
516:       if (dx * dx + dy * dy + dz * dz < 1.6 * 1.6) {
517:         this.collectPickup(p);
518:         if (!p.alive) this.pickups.splice(i, 1);
519:       }
520:     }
521: 
522:     for (const c of this.crates) c.update(dt);
523:     for (const n of this.nodes) n.update(dt);
524: 
525:     this.updateStorm(dt);
526:     this.updateInteraction(dt);
527:     this.updateExtraction(dt);
528:     if (this.state !== 'playing') return;
529: 
530:     for (let i = this.respawnQueue.length - 1; i >= 0; i--) {
531:       const r = this.respawnQueue[i];
532:       r.t -= dt;
533:       if (r.t <= 0) {
534:         this.respawnQueue.splice(i, 1);
535:         if (this.enemies.filter((e) => e.alive).length < 9) {
536:           const p = this.randomSpawnPoint();
537:           this.spawnDrone(p.x, p.z, chance(0.22) ? 'heavy' : 'scout');
538:         }
539:       }
540:     }
541: 
542:     this.effects.update(dt);
543:     this.world.update(dt, this.time, this.storm.active, this.player.pos);
544: 
545:     this.ui.updateMarkers(this.camera, true);
546:     this.updateHUD();
547:   }
