549:   handleGamepad() {
550:     const pad = this.gamepad;
551:     if (!pad.connected) return;
552: 
553:     // The field manual is a DOM overlay; controller Start/Back dismisses it.
554:     const helpOpen = !!(this.isHelpOpen && this.isHelpOpen());
555:     if (helpOpen) {
556:       if (pad.start || pad.back) this.closeHelp?.();
557:       return;
558:     }
559: 
560:     if (pad.help) {
561:       if (this.state === 'playing') {
562:         this.pause();
563:         this.openHelp?.('pause');
564:       } else if (this.state === 'paused') {
565:         this.openHelp?.('pause');
566:       } else if (this.state === 'menu') {
567:         this.openHelp?.('start');
568:       }
569:       return;
570:     }
571: 
572:     if (pad.pause && this.state === 'playing') {
573:       this.pause();
574:       return;
575:     }
576: 
577:     if (pad.start) {
578:       if (this.state === 'menu') {
579:         this.startRun();
580:         pad.consume('jump');
581:         pad.consume('start');
582:         return;
583:       }
584:       if (this.state === 'paused') {
585:         this.resume();
586:         pad.consume('start');
587:         return;
588:       }
589:       if ((this.state === 'dead' || this.state === 'extracted')
590:         && !this.ui.el.end.classList.contains('hidden')
591:         && performance.now() - this.endAt > 800) {
592:         this.startRun();
593:         pad.consume('jump');
594:         pad.consume('start');
595:         return;
596:       }
597:     }
598: 
599:     if (this.state !== 'playing') return;
600: 
601:     if (pad.reload) this.player.reload();
602:     if (pad.nextWeapon) this.player.cycleWeapon();
603:     if (pad.prevWeapon) {
604:       const count = this.player.weapons.length;
605:       this.player.switchWeapon((this.player.weaponIndex + count - 1) % count);
606:     }
607:   }
