662:   fireHitscan(origin, dir, opts = {}) {
663:     const damage = opts.damage ?? 30;
664:     const drawTracer = opts.tracer !== false;
665:     const tracerColor = opts.color ?? 0xfff2cf;
666:     let enemyHit = null;
667:     let enemyDist = Infinity;
668: 
669:     for (const e of this.enemies) {
670:       if (!e.alive) continue;
671:       const oc = this.tmpV.copy(e.group.position).sub(origin);
672:       const t = oc.dot(dir);
673:       if (t < 0 || t > 300) continue;
674:       const d2 = oc.lengthSq() - t * t;
675:       if (d2 <= e.hitRadius * e.hitRadius && t < enemyDist) {
676:         enemyDist = t;
677:         enemyHit = e;
678:       }
679:     }
680: 
681:     this.raycaster.set(origin, dir);
682:     this.raycaster.far = Math.min(300, enemyDist);
683:     const hits = this.raycaster.intersectObjects(this.world.shootables, false);
684: 
685:     if (hits.length) {
686:       const h = hits[0];
687:       this.effects.impact(h.point, 0xffc27a, 4);
688:       if (drawTracer) this.effects.tracer(origin, h.point, tracerColor);
689:       return;
690:     }
691: 
692:     if (enemyHit) {
693:       const point = origin.clone().addScaledVector(dir, enemyDist);
694:       const killed = enemyHit.hit(damage, this.ctx, point);
695:       if (drawTracer) this.effects.tracer(origin, point, tracerColor);
696:       this.ui.hitmarker(killed);
697:       this.audio.hit(killed);
698:       return;
699:     }
700: 
701:     const end = origin.clone().addScaledVector(dir, 150);
702:     if (drawTracer) this.effects.tracer(origin, end, tracerColor);
703:   }
