140:       pod.position.set(0, -0.28, -0.35);
141:       group.add(pod);
142:       const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.4, 8), hullMat);
143:       barrel.rotation.x = Math.PI / 2;
144:       barrel.position.set(0, -0.28, -0.75);
145:       group.add(barrel);
146:     }
147: 
148:     group.position.copy(this.anchor);
149:     group.position.y = terrainHeight(this.anchor.x, this.anchor.z) + this.altitude;
150:     this.scene.add(group);
151:   }
152: 
153:   update(dt, ctx) {
154:     if (!this.alive) return;
155:     this.t += dt;
156:     this.flash = Math.max(0, this.flash - dt * 6);
157: 
158:     const player = ctx.player;
159:     const px = player.pos.x, pz = player.pos.z;
160:     const pos = this.group.position;
161:     const dx = px - pos.x, dz = pz - pos.z;
162:     const dist = Math.hypot(dx, dz);
163: 
164:     const playerAlive = player.health > 0;
165:     const detectRange = (this.heavy ? 52 : 44) + (ctx.storm ? 12 : 0);
166:     const engageRange = this.heavy ? 34 : 30;
167: 
168:     if (playerAlive && dist < detectRange) {
169:       this.state = 'engage';
170:       this.alert = Math.min(1, this.alert + dt * 1.6);
171:       if (!this.alertedOnce) {
172:         this.alertedOnce = true;
173:         ctx.game.audio.alert();
174:       }
175:     } else {
176:       this.state = 'patrol';
177:       this.alert = Math.max(0, this.alert - dt);
178:       this.alertedOnce = false;
179:     }
180: 
181:     let targetVX = 0;
182:     let targetVZ = 0;
183: 
184:     if (this.state === 'engage') {
185:       this.angle += dt * 0.6;
186:       const desired = this.heavy ? 19 : 15;
187:       const nx = dx / (dist || 1);
188:       const nz = dz / (dist || 1);
189:       const radial = clamp((dist - desired) / 8, -1, 1);
190:       const strafe = Math.sin(this.t * 0.9 + this.phase) * 0.75;
191: 
192:       targetVX = nx * radial * this.speed + -nz * strafe * this.speed * 0.55;
193:       targetVZ = nz * radial * this.speed + nx * strafe * this.speed * 0.55;
194: 
195:       // firing
196:       this.fireCd -= dt;
197:       if (dist < engageRange && this.fireCd <= 0) {
198:         if (this.burst <= 0) this.burst = this.heavy ? 3 : 2;
199:         this.burstCd -= dt;
200:         if (this.burstCd <= 0) {
201:           this.fire(ctx, dist);
202:           this.burst--;
203:           this.burstCd = 0.13;
204:           if (this.burst <= 0) {
205:             this.fireCd = this.fireInterval * (ctx.storm ? 0.78 : 1) * rand(0.85, 1.2);
206:             this.burstCd = 0;
207:           }
208:         }
209:       }
210:     } else {
211:       this.angle += dt * 0.24;
212:       const radius = this.heavy ? 10 : 8;
213:       const tx = this.anchor.x + Math.cos(this.angle) * radius;
214:       const tz = this.anchor.z + Math.sin(this.angle) * radius;
215:       const ddx = tx - pos.x, ddz = tz - pos.z;
216:       const dl = Math.hypot(ddx, ddz) || 1;
217:       targetVX = (ddx / dl) * this.speed * 0.35;
218:       targetVZ = (ddz / dl) * this.speed * 0.35;
219:     }
220: 
221:     this.vel.x = damp(this.vel.x, targetVX, 2.2, dt);
222:     this.vel.z = damp(this.vel.z, targetVZ, 2.2, dt);
223:     pos.x += this.vel.x * dt;
224:     pos.z += this.vel.z * dt;
225:     pos.x = clamp(pos.x, -215, 215);
226:     pos.z = clamp(pos.z, -215, 215);
227: 
228:     const ground = terrainHeight(pos.x, pos.z);
229:     const bob = Math.sin(this.t * 1.7 + this.phase) * 0.22;
230:     const desiredY = ground + this.altitude + bob;
231:     pos.y = damp(pos.y, desiredY, 3, dt);
232: 
233:     // face the player when engaged
234:     if (this.state === 'engage') {
235:       const targetYaw = Math.atan2(dx, dz) + Math.PI;
236:       let diff = ((targetYaw - this.group.rotation.y + Math.PI) % TAU + TAU) % TAU - Math.PI;
237:       this.group.rotation.y += diff * Math.min(1, dt * 3.5);
238:     } else {
239:       this.group.rotation.y += dt * 0.35;
240:     }
241: 
242:     // visual state
243:     const alertColor = this.state === 'engage' ? 0xff3b46 : 0x79f2ff;
244:     this.eyeMat.color.setHex(alertColor);
245:     this.ringMat.color.setHex(this.state === 'engage' ? 0xff5a3a : 0x2f8f9e);
246:     this.ring.rotation.z += dt * 2.5;
247:     this.hullMat.emissive.setRGB(this.flash * 0.9, this.flash * 0.75, this.flash * 0.5);
248:     this.hullMat.emissiveIntensity = 1;
249:   }
250: 
251:   fire(ctx, dist) {
252:     const origin = this.group.position.clone();
253:     origin.y -= 0.15;
254:     const target = ctx.player.pos.clone();
255:     target.y += 1.1;
256:     const dir = target.sub(origin).normalize();
257:     dir.x += rand(-0.03, 0.03);
258:     dir.y += rand(-0.02, 0.02);
259:     dir.z += rand(-0.03, 0.03);
260:     dir.normalize();
261:     ctx.game.spawnBolt(origin, dir, {
262:       damage: this.damage,
263:       speed: this.boltSpeed,
264:       scale: this.heavy ? 1.5 : 1,
265:     });
266:     ctx.effects.muzzle(origin, 0xffa14a);
267:     ctx.game.audio.enemyShot(dist);
268:   }
269: 
270:   hit(amount, ctx, point) {
271:     if (!this.alive) return false;
272:     this.health -= amount;
273:     this.flash = 1;
274:     this.state = 'engage';
275:     this.alert = 1;
276:     if (this.health <= 0) {
277:       this.die(ctx);
278:       return true;
279:     }
280:     ctx.effects.spark(point || this.group.position, 0x9fe8ff, 4);
281:     return false;
282:   }
283: 
284:   die(ctx) {
285:     this.alive = false;
286:     ctx.effects.explosion(this.group.position, this.heavy ? 0xff7a2b : 0x79f2ff, this.heavy ? 22 : 13);
287:     this.scene.remove(this.group);
288:     ctx.game.onDroneKilled(this);
289:   }
290: }

