/* ============================================================
   AETHELGARD — Ether-Core Extraction
   HUD + menu styling
   ============================================================ */

@font-face {
  font-family: 'Orbitron';
  src: url('assets/fonts/orbitron.woff2') format('woff2');
  font-weight: 400 900;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('assets/fonts/rajdhani-400.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('assets/fonts/rajdhani-500.woff2') format('woff2');
  font-weight: 500;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('assets/fonts/rajdhani-600.woff2') format('woff2');
  font-weight: 600;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('assets/fonts/rajdhani-700.woff2') format('woff2');
  font-weight: 700;
  font-display: swap;
}

:root {
  --amber: #ffb057;
  --amber-hot: #ff8a2b;
  --amber-dim: rgba(255, 176, 87, .42);
  --cyan: #79f2ff;
  --cyan-dim: rgba(121, 242, 255, .35);
  --danger: #ff4d5e;
  --good: #8dffb0;
  --ink: #080605;
  --ink-2: #0e0b09;
  --panel: rgba(12, 9, 8, .66);
  --line: rgba(255, 226, 197, .16);
  --text: #f4ece2;
  --muted: #a89a8b;
  --ui: 'Rajdhani', 'DIN Condensed', 'Segoe UI', sans-serif;
  --display: 'Orbitron', 'Impact', sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body {
  background: var(--ink);
  color: var(--text);
  font-family: var(--ui);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}
canvas#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}
.hidden { display: none !important; }
b, strong { font-weight: 700; }
kbd {
  font-family: var(--ui);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: .08em;
  padding: 2px 5px;
  border: 1px solid rgba(255, 226, 197, .28);
  border-bottom-width: 2px;
  border-radius: 3px;
  background: rgba(255, 255, 255, .04);
  color: #f6e9da;
  display: inline-block;
  min-width: 18px;
  text-align: center;
}
button { font-family: inherit; }

/* ============================================================
   HUD
   ============================================================ */

#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  letter-spacing: .04em;
}
#hud .hud-scanlines {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(to bottom, rgba(255,255,255,.022) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
  opacity: .55;
  pointer-events: none;
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 18px;
  padding: 18px 24px 0;
}

.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark {
  width: 30px; height: 34px;
  display: grid; place-items: center;
  font-family: var(--display);
  font-weight: 800;
  font-size: 17px;
  color: #140d07;
  background: linear-gradient(180deg, #ffd39a, var(--amber-hot));
  clip-path: polygon(0 0, 100% 0, 100% 72%, 50% 100%, 0 72%);
  box-shadow: 0 0 22px rgba(255, 138, 43, .45);
}
.brand-text { display: flex; flex-direction: column; line-height: 1; }
.brand-text strong {
  font-family: var(--display);
  font-size: 14px;
  letter-spacing: .22em;
  color: #fff4e6;
}
.brand-text small {
  font-size: 9px;
  letter-spacing: .28em;
  color: var(--muted);
  margin-top: 5px;
}

.storm { width: min(30vw, 320px); text-align: center; padding-top: 2px; }
.storm-label {
  font-size: 9px; letter-spacing: .3em; color: var(--muted);
  display: block; margin-bottom: 6px;
}
.storm-bar {
  height: 4px;
  background: rgba(255, 255, 255, .1);
  overflow: hidden;
  position: relative;
  clip-path: polygon(0 0, 100% 0, calc(100% - 4px) 100%, 4px 100%);
}
.storm-bar i {
  position: absolute; inset: 0 auto 0 0;
  width: 100%;
  background: linear-gradient(90deg, var(--amber-dim), var(--amber));
  transition: width .2s linear, background .4s;
}
.storm-text {
  display: block; margin-top: 6px;
  font-size: 10px; letter-spacing: .28em; color: #d8c6b2;
}
.storm.warn .storm-text { color: var(--amber); }
.storm.storming .storm-text { color: var(--danger); text-shadow: 0 0 10px rgba(255, 77, 94, .7); }
.storm.storming .storm-bar i { background: linear-gradient(90deg, #8a2c22, var(--danger)); }
.storm.warn { animation: stormPulse 1.1s ease-in-out infinite; }
@keyframes stormPulse { 50% { opacity: .62; } }

.wallet { justify-self: end; display: flex; align-items: center; gap: 16px; }
.wallet-row { display: flex; align-items: baseline; gap: 7px; }
.cur { font-size: 9px; letter-spacing: .22em; color: var(--muted); }
.cur.aether { color: var(--cyan); }
.wallet-row b {
  font-family: var(--ui);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: .04em;
  color: #fff4e6;
  min-width: 34px;
  text-align: right;
}
.wallet-row:nth-child(2) b { color: var(--cyan); text-shadow: 0 0 14px rgba(121, 242, 255, .35); }

.pad-chip {
  position: absolute;
  top: 68px;
  left: 24px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 10px 4px 8px;
  border: 1px solid rgba(121, 242, 255, .28);
  background: rgba(8, 14, 15, .56);
  color: #c8f6fb;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: .22em;
  text-transform: uppercase;
  clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%);
}
.pad-chip i {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
  animation: padPulse 1.7s ease-in-out infinite;
}
@keyframes padPulse { 50% { opacity: .35; } }

.icon-btn {
  pointer-events: auto;
  width: 30px; height: 30px;
  display: grid; place-items: center;

  display: grid; place-items: center;
  background: rgba(255, 255, 255, .04);
  border: 1px solid var(--line);
  color: #cbbcab;
  cursor: pointer;
  transition: .2s;
}
.icon-btn:hover { color: var(--amber); border-color: var(--amber-dim); background: rgba(255, 176, 87, .08); }
.icon-btn svg { width: 15px; height: 15px; fill: currentColor; }
.icon-btn.muted { color: #6d6157; }
.icon-btn.muted::after {
  content: ''; position: absolute; width: 18px; height: 1px; background: var(--danger);
  transform: rotate(-45deg);
}

.objective {
  position: absolute;
  top: 92px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px;
  background: linear-gradient(90deg, rgba(10,8,7,0), rgba(10,8,7,.62) 18%, rgba(10,8,7,.62) 82%, rgba(10,8,7,0));
  font-size: 12px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: #e6d8c8;
  white-space: nowrap;
}
.objective-tag {
  font-size: 9px;
  letter-spacing: .3em;
  color: var(--amber);
  border-right: 1px solid var(--line);
  padding-right: 10px;
}

/* crosshair */
.crosshair {
  position: fixed; left: 50%; top: 50%;
  width: 0; height: 0;
  --gap: 7px;
  opacity: .9;
}
.crosshair i {
  position: absolute;
  background: #fff;
  box-shadow: 0 0 5px rgba(0, 0, 0, .8);
  transition: transform .06s linear;
}
.crosshair i:nth-child(1) { width: 2px; height: 8px; left: -1px; top: calc(-1 * var(--gap) - 8px); }
.crosshair i:nth-child(2) { width: 2px; height: 8px; left: -1px; top: var(--gap); }
.crosshair i:nth-child(3) { width: 8px; height: 2px; top: -1px; left: calc(-1 * var(--gap) - 8px); }
.crosshair i:nth-child(4) { width: 8px; height: 2px; top: -1px; left: var(--gap); }
.crosshair .dot { display: none; }

.hitmarker {
  position: fixed; left: 50%; top: 50%;
  width: 0; height: 0;
  opacity: 0;
}
.hitmarker i {
  position: absolute; width: 12px; height: 2px;
  background: #fff;
  box-shadow: 0 0 6px rgba(255, 255, 255, .9);
}
.hitmarker i:nth-child(1) { transform: translate(-11px, -8px) rotate(45deg); }
.hitmarker i:nth-child(2) { transform: translate(1px, -8px) rotate(-45deg); }
.hitmarker i:nth-child(3) { transform: translate(-11px, 7px) rotate(-45deg); }
.hitmarker i:nth-child(4) { transform: translate(1px, 7px) rotate(45deg); }
.hitmarker.show { animation: hitPop .22s ease-out; }
.hitmarker.kill i { background: var(--danger); }
@keyframes hitPop {
  0% { opacity: 1; transform: scale(1.25); }
  100% { opacity: 0; transform: scale(1); }
}

.markers { position: absolute; inset: 0; overflow: hidden; }
.marker {
  position: absolute;
  transform: translate(-50%, -100%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  font-size: 9px; letter-spacing: .22em;
  color: var(--amber);
  text-shadow: 0 1px 6px #000;
  transition: opacity .2s;
}
.marker .m-icon {
  width: 13px; height: 13px;
  border: 1px solid currentColor;
  transform: rotate(45deg);
  box-shadow: 0 0 12px rgba(255, 176, 87, .35);
}
.marker.cyan { color: var(--cyan); }
.marker .m-dist { color: rgba(255, 255, 255, .72); font-size: 9px; letter-spacing: .14em; }

/* toasts */
.toasts {
  position: absolute;
  right: 24px;
  top: 84px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  width: 280px;
}
.toast {
  padding: 6px 12px;
  background: rgba(10, 8, 7, .78);
  border-left: 2px solid var(--amber);
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #f1e4d4;
  animation: toastIn .25s ease-out;
  backdrop-filter: blur(4px);
}
.toast.cyan { border-color: var(--cyan); color: #d8fbff; }
.toast.danger { border-color: var(--danger); color: #ffd9dc; }
.toast.out { animation: toastOut .35s ease-in forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(18px); } }

/* prompt */
.prompt {
  position: absolute;
  left: 50%; bottom: 21%;
  transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  padding: 9px 16px 12px;
  background: rgba(10, 8, 7, .78);
  border: 1px solid var(--amber-dim);
  font-size: 12px;
  letter-spacing: .18em;
  text-transform: uppercase;
  white-space: nowrap;
  backdrop-filter: blur(6px);
}
.prompt kbd { border-color: var(--amber); color: var(--amber); }
.prompt-progress {
  position: absolute; left: 0; right: 0; bottom: 0; height: 2px;
  background: rgba(255, 255, 255, .1);
}
.prompt-progress i { display: block; height: 100%; width: 0; background: var(--amber); }

/* extraction */
.extract-panel {
  position: absolute;
  left: 50%; top: 19%;
  transform: translateX(-50%);
  text-align: center;
  padding: 14px 30px 18px;
  background: radial-gradient(ellipse at center, rgba(10,8,7,.86), rgba(10,8,7,.4) 70%, transparent);
  min-width: 300px;
}
.extract-kicker { display: block; font-size: 9px; letter-spacing: .32em; color: var(--cyan); }
.extract-panel strong {
  display: block;
  font-family: var(--display);
  font-size: 44px;
  line-height: 1.1;
  color: #fff;
  text-shadow: 0 0 26px rgba(121, 242, 255, .45);
}
.extract-sub { display: block; font-size: 9px; letter-spacing: .26em; color: var(--muted); margin-bottom: 10px; }
.extract-bar { height: 3px; background: rgba(255,255,255,.12); }
.extract-bar i { display: block; height: 100%; width: 0; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); }

/* bottom HUD */
.hud-bottom {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 20px;
  padding: 0 24px 22px;
}
.vitals { display: flex; flex-direction: column; gap: 8px; width: min(280px, 26vw); }
.vital-row { display: grid; grid-template-columns: 58px 1fr 30px; align-items: center; gap: 8px; }
.vital-label { font-size: 9px; letter-spacing: .22em; color: var(--muted); }
.vital-row b { font-family: var(--ui); font-size: 13px; font-weight: 700; text-align: right; color: #eadccb; }
.bar { height: 6px; background: rgba(255, 255, 255, .1); overflow: hidden; }
.bar i { display: block; height: 100%; width: 100%; transition: width .18s; }
.bar.health i { background: linear-gradient(90deg, #b53a34, #ff7a5c); box-shadow: 0 0 12px rgba(255, 90, 70, .35); }
.bar.stamina i { background: linear-gradient(90deg, #7c6a2c, #f0cf6a); }
.vitals.low .bar.health i { background: linear-gradient(90deg, #7c1515, var(--danger)); animation: lowPulse .8s infinite; }
@keyframes lowPulse { 50% { opacity: .45; } }

.cargo {
  text-align: center;
  padding: 8px 22px 9px;
