    this.beginStep();
  }
  beginStep() {
    const step = this.steps[this.current];
    if (!step) return;
    step.started = true;
    this.kills = 0;
    // activate props for step
    for (const p of this.props) p.active = p.def.step === step.id && !p.used;
    // spawn for kill step
    if (step.type === 'kill' && step.spawn) { ... spawn wave ... }
    if (step.type === 'kill' && step.spawnBoss) ...
    // waypoint
